INSERT INTO curated_plant_content(product_code,expected_name,latin,short_text,full_text,care_text,light,watering) VALUES
  (851,'Антуриум Блэк Бьюти (Anthurium Black Beauty) D17','Anthurium','Цветущий антуриум с глянцевыми листьями и соцветием из покрывала и початка.','У антуриума яркое покрывало окружает початок с мелкими цветками. Он подходит для тёплого светлого места без прямых полуденных лучей; окраска и размер соцветий зависят от конкретного сорта.','Поставьте в яркий рассеянный свет. Поливайте, когда верхний слой субстрата начинает подсыхать, и сливайте лишнюю воду. Держите в тепле, вдали от холодных сквозняков; для корней нужен рыхлый дренированный субстрат.','diffused','moderate'),
  (852,'Антуриум Блэк Лав (Andreanum «Black Love») D17','Anthurium','Цветущий антуриум с глянцевыми листьями и соцветием из покрывала и початка.','У антуриума яркое покрывало окружает початок с мелкими цветками. Он подходит для тёплого светлого места без прямых полуденных лучей; окраска и размер соцветий зависят от конкретного сорта.','Поставьте в яркий рассеянный свет. Поливайте, когда верхний слой субстрата начинает подсыхать, и сливайте лишнюю воду. Держите в тепле, вдали от холодных сквозняков; для корней нужен рыхлый дренированный субстрат.','diffused','moderate'),
  (855,'Антуриум Мелодия Ибис (Anthurium Melodia Ibis) D17','Anthurium','Цветущий антуриум с глянцевыми листьями и соцветием из покрывала и початка.','У антуриума яркое покрывало окружает початок с мелкими цветками. Он подходит для тёплого светлого места без прямых полуденных лучей; окраска и размер соцветий зависят от конкретного сорта.','Поставьте в яркий рассеянный свет. Поливайте, когда верхний слой субстрата начинает подсыхать, и сливайте лишнюю воду. Держите в тепле, вдали от холодных сквозняков; для корней нужен рыхлый дренированный субстрат.','diffused','moderate'),
  (853,'Араукария 20 см D10','Araucaria','Араукария с симметричными ярусами мягких хвойных ветвей.','Араукария напоминает небольшое комнатное хвойное дерево. Её аккуратный ярусный силуэт лучше сохраняется при равномерном освещении и достаточном пространстве вокруг кроны.','Выберите светлое место и защищайте растение от холодных сквозняков. В период роста поливайте после лёгкого подсыхания поверхности грунта; зимой при замедлении роста полив сокращайте. Не оставляйте воду в поддоне.','diffused','moderate'),
  (856,'Диффенбахия Reflector Д22','Dieffenbachia ''Reflector''','Диффенбахия «Рефлектор» с крупными пёстрыми листьями.','У диффенбахии «Рефлектор» декоративные овальные листья с пятнистым рисунком. Главный акцент этой карточки — листва; редкое комнатное цветение не используется как обещание.','Держите в ярком рассеянном свете без прямого полуденного солнца. Поливайте после подсыхания верхнего слоя субстрата и сливайте воду из поддона. Берегите от холода и сквозняков.','diffused','moderate'),
  (857,'Замиокулькус Roundleaf D22','Zamioculcas zamiifolia','Замиокулькас с плотными глянцевыми листьями и запасом влаги в корневищах.','Замиокулькас образует прямостоячие побеги с плотными блестящими листочками. Мясистые корневища запасают влагу, поэтому для растения особенно опасен застой воды в горшке.','Лучше всего растёт при ярком рассеянном свете, переносит полутень. Давайте грунту хорошо просохнуть между поливами; после полива сливайте воду из кашпо. Зимой поливайте реже.','diffused','rare'),
  (566,'Замиокулькас','Zamioculcas zamiifolia','Замиокулькас с плотными глянцевыми листьями и запасом влаги в корневищах.','Замиокулькас образует прямостоячие побеги с плотными блестящими листочками. Мясистые корневища запасают влагу, поэтому для растения особенно опасен застой воды в горшке.','Лучше всего растёт при ярком рассеянном свете, переносит полутень. Давайте грунту хорошо просохнуть между поливами; после полива сливайте воду из кашпо. Зимой поливайте реже.','diffused','rare'),
  (865,'Кордилина  Киви D10','Cordyline fruticosa ''Kiwi''','Кордилина «Киви» с зелёными листьями, жёлтыми полосами и розовой каймой.','Сорт «Киви» узнаваем по глянцевым ремневидным листьям: зелёный фон пересекают жёлтые штрихи, а края окрашены в розовый. Это декоративно-лиственное растение для тёплого светлого места.','Держите в ярком рассеянном свете. Поливайте умеренно в период роста, после лёгкого подсыхания верхнего слоя; зимой реже. Избегайте застоя воды и холодных сквозняков.','diffused','moderate'),
  (859,'Нефролепис даффи','Nephrolepis','Папоротник нефролепис с дуговидными ажурными вайями.','Нефролепис образует густую зелёную массу из перистых вай. Он хорошо смотрится там, где листве достаточно места для свободного роста; конкретная форма вай зависит от сорта.','Поставьте в яркий фильтрованный свет. Поддерживайте грунт умеренно влажным, не пересушивая ком и не оставляя корни в воде. Берегите от сухого горячего воздуха; зимой поливайте осторожнее.','diffused','moderate'),
  (860,'Нефролепис «Тедди Джуниор» D17','Nephrolepis','Папоротник нефролепис с дуговидными ажурными вайями.','Нефролепис образует густую зелёную массу из перистых вай. Он хорошо смотрится там, где листве достаточно места для свободного роста; конкретная форма вай зависит от сорта.','Поставьте в яркий фильтрованный свет. Поддерживайте грунт умеренно влажным, не пересушивая ком и не оставляя корни в воде. Берегите от сухого горячего воздуха; зимой поливайте осторожнее.','diffused','moderate'),
  (506,'Нефролепис «Грин Леди»','Nephrolepis','Папоротник нефролепис с дуговидными ажурными вайями.','Нефролепис образует густую зелёную массу из перистых вай. Он хорошо смотрится там, где листве достаточно места для свободного роста; конкретная форма вай зависит от сорта.','Поставьте в яркий фильтрованный свет. Поддерживайте грунт умеренно влажным, не пересушивая ком и не оставляя корни в воде. Берегите от сухого горячего воздуха; зимой поливайте осторожнее.','diffused','moderate'),
  (155,'Нефролепис Бостон Блонди','Nephrolepis','Папоротник нефролепис с дуговидными ажурными вайями.','Нефролепис образует густую зелёную массу из перистых вай. Он хорошо смотрится там, где листве достаточно места для свободного роста; конкретная форма вай зависит от сорта.','Поставьте в яркий фильтрованный свет. Поддерживайте грунт умеренно влажным, не пересушивая ком и не оставляя корни в воде. Берегите от сухого горячего воздуха; зимой поливайте осторожнее.','diffused','moderate'),
  (156,'Нефролепис Грин Леди','Nephrolepis','Папоротник нефролепис с дуговидными ажурными вайями.','Нефролепис образует густую зелёную массу из перистых вай. Он хорошо смотрится там, где листве достаточно места для свободного роста; конкретная форма вай зависит от сорта.','Поставьте в яркий фильтрованный свет. Поддерживайте грунт умеренно влажным, не пересушивая ком и не оставляя корни в воде. Берегите от сухого горячего воздуха; зимой поливайте осторожнее.','diffused','moderate'),
  (157,'Нефролепис Коттон Кэнди','Nephrolepis','Папоротник нефролепис с дуговидными ажурными вайями.','Нефролепис образует густую зелёную массу из перистых вай. Он хорошо смотрится там, где листве достаточно места для свободного роста; конкретная форма вай зависит от сорта.','Поставьте в яркий фильтрованный свет. Поддерживайте грунт умеренно влажным, не пересушивая ком и не оставляя корни в воде. Берегите от сухого горячего воздуха; зимой поливайте осторожнее.','diffused','moderate'),
  (158,'Нефролепис Тайгер','Nephrolepis','Папоротник нефролепис с дуговидными ажурными вайями.','Нефролепис образует густую зелёную массу из перистых вай. Он хорошо смотрится там, где листве достаточно места для свободного роста; конкретная форма вай зависит от сорта.','Поставьте в яркий фильтрованный свет. Поддерживайте грунт умеренно влажным, не пересушивая ком и не оставляя корни в воде. Берегите от сухого горячего воздуха; зимой поливайте осторожнее.','diffused','moderate'),
  (867,'Традесканция Зебрина D 10','Tradescantia zebrina','Традесканция зебрина с полосатыми листьями и свисающими побегами.','Серебристые полосы на верхней стороне листьев контрастируют с пурпурной нижней стороной. Гибкие побеги можно пустить по краю полки или подвесного кашпо.','Дайте яркий рассеянный свет для сохранения рисунка листьев. Поливайте после подсыхания верхнего слоя грунта; зимой сократите полив. Прищипывайте вытянувшиеся побеги для более густой формы.','diffused','moderate'),
  (861,'Хлорофитум кудрявый D10','Chlorophytum','Хлорофитум с дуговидными листьями и возможными дочерними розетками на побегах.','Хлорофитум образует пучок узких листьев; у взрослых растений могут появляться длинные побеги с молодыми розетками. Поэтому растение удобно поставить на полку или в подвесное кашпо.','Выберите рассеянный свет без сильного прямого солнца. Поливайте после подсыхания верхнего слоя грунта и не оставляйте воду в поддоне. Зимой поливайте реже.','diffused','moderate'),
  (807,'Хлорофитум','Chlorophytum','Хлорофитум с дуговидными листьями и возможными дочерними розетками на побегах.','Хлорофитум образует пучок узких листьев; у взрослых растений могут появляться длинные побеги с молодыми розетками. Поэтому растение удобно поставить на полку или в подвесное кашпо.','Выберите рассеянный свет без сильного прямого солнца. Поливайте после подсыхания верхнего слоя грунта и не оставляйте воду в поддоне. Зимой поливайте реже.','diffused','moderate'),
  (233,'Хлорофитум','Chlorophytum','Хлорофитум с дуговидными листьями и возможными дочерними розетками на побегах.','Хлорофитум образует пучок узких листьев; у взрослых растений могут появляться длинные побеги с молодыми розетками. Поэтому растение удобно поставить на полку или в подвесное кашпо.','Выберите рассеянный свет без сильного прямого солнца. Поливайте после подсыхания верхнего слоя грунта и не оставляйте воду в поддоне. Зимой поливайте реже.','diffused','moderate'),
  (2,'Аглаонема Вайт Ленс','Aglaonema','Аглаонема с декоративным рисунком на плотных листьях.','Аглаонемы выращивают ради листвы: окраска и рисунок заметно различаются между сортами. Растение образует компактный куст и подходит для места с мягким рассеянным светом.','Поставьте в рассеянный свет; прямое солнце может обжечь листья. Поливайте после частичного подсыхания субстрата и не используйте холодную воду. Зимой поливайте реже.','diffused','moderate'),
  (12,'Аглаонема Чайна Ред','Aglaonema','Аглаонема с декоративным рисунком на плотных листьях.','Аглаонемы выращивают ради листвы: окраска и рисунок заметно различаются между сортами. Растение образует компактный куст и подходит для места с мягким рассеянным светом.','Поставьте в рассеянный свет; прямое солнце может обжечь листья. Поливайте после частичного подсыхания субстрата и не используйте холодную воду. Зимой поливайте реже.','diffused','moderate'),
